/* ==========================================================================
   Task 1: Navigation Bar Layout
   ========================================================================== */
.navbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 64px;
  padding: 0 24px;
  background-color: #1e293b;
  color: #ffffff;
}

/* ==========================================================================
   Task 2: Centered Modal Overlay Layout
   ========================================================================== */
.modal-backdrop {
  display: flex;
  justify-content: center;
  align-items: center;
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background-color: rgba(0, 0, 0, 0.5);
}
